"""P3: the config repo (template, example fixture, pin, locks, expiry) and `mcctl validate` on it."""

import shutil
import subprocess

import pytest
import yaml
from conftest import EXAMPLE, REPO, TEST_SHA, make_config_repo

from mcctl import cli, configrepo

SHA_A = "a" * 40


def test_example_is_the_materialized_template(tmp_path) -> None:
    # examples/config-repo is regenerated by scripts/sync_example.py; it must not drift from template/.
    fresh = tmp_path / "fresh"
    configrepo.materialize(fresh, sha="0" * 40, version="v0.0.0")
    on_disk = sorted(p.relative_to(EXAMPLE) for p in EXAMPLE.rglob("*") if p.is_file())
    assert on_disk == configrepo.template_files()
    for rel in on_disk:
        assert (EXAMPLE / rel).read_text() == (fresh / rel).read_text(), f"{rel}: run scripts/sync_example.py"


def test_template_has_the_config_repo_layout() -> None:
    names = {p.as_posix() for p in configrepo.template_files()}
    assert names == {
        "server.yml",
        "players.yml",
        "server.lock.yml",
        "plugins.lock.yml",
        "client.lock.yml",
        "expiry.yml",
        ".env.example",
        ".gitignore",
        "README.md",
        ".github/workflows/server.yml",
    }


def test_throwaway_config_repo_validates_against_this_product_sha(tmp_path, capsys) -> None:
    # P3 acceptance (local half; CI's config-repo job runs the real reusable workflow at the commit):
    # a fresh git repo made from the template, pinned to this checkout's commit, passes `mcctl validate`.
    git = shutil.which("git")
    if git is None:
        pytest.skip("needs git")
    sha = subprocess.run([git, "-C", str(REPO), "rev-parse", "HEAD"], capture_output=True, text=True).stdout
    sha = sha.strip() if configrepo.SHA.fullmatch(sha.strip()) else TEST_SHA
    root = tmp_path / "throwaway-config"
    configrepo.materialize(root, sha=sha, version="v0.3.0")
    subprocess.run([git, "init", "-q", str(root)], check=True)
    out = tmp_path / "github-output"
    assert cli.main(["validate", "-C", str(root), "--github-output", str(out)]) == 0
    captured = capsys.readouterr()
    assert f"valid (product {configrepo.PRODUCT_REPOSITORY}@{sha[:12]})" in captured.out
    assert "is a placeholder" in captured.err  # warned, not fatal: validate runs on every PR
    assert dict(line.split("=", 1) for line in out.read_text().splitlines()) == {
        "deploy_enabled": "false",
        "tailscale_name": "example",
        "server_address": "mc.example.com",
        "deploy_environment": "deploy",  # the template sets github.environments: true
        "update_environment": "update",
        "product_repository": configrepo.PRODUCT_REPOSITORY,
        "product_version": "v0.3.0",
    }


def test_example_validates_with_warnings(capsys) -> None:
    assert cli.main(["validate", "-C", str(EXAMPLE)]) == 0
    assert "warning: admin.tailscale_login" in capsys.readouterr().err


def test_missing_files_are_listed(tmp_path, capsys) -> None:
    root = make_config_repo(tmp_path / "c")
    for name in ("server.lock.yml", "plugins.lock.yml", ".github/workflows/server.yml"):
        (root / name).unlink()
    (root / "players.yml").unlink()  # optional
    (root / "expiry.yml").unlink()  # optional
    with pytest.raises(configrepo.ConfigError) as exc:
        configrepo.load(root)
    assert exc.value.errors == [
        "server.lock.yml: missing",
        "plugins.lock.yml: missing",
        ".github/workflows/server.yml: missing (the pinned call of the product's reusable workflow)",
    ]


# --- the pin -------------------------------------------------------------------------------------------


def wf(uses: str, extra: str = "") -> str:
    return f"jobs:\n  server:\n    uses: {uses}\n{extra}"


def test_pin_by_sha() -> None:
    pin, errors = configrepo.read_pin(wf(f"o/r/.github/workflows/server.yml@{SHA_A} # v1.2.3"))
    assert errors == [] and pin == configrepo.Pin("o/r", SHA_A, "v1.2.3")
    pin, errors = configrepo.read_pin(wf(f"o/r/.github/workflows/server.yml@{SHA_A}"))
    assert pin == configrepo.Pin("o/r", SHA_A, None)


@pytest.mark.parametrize(
    ("text", "fragment"),
    [
        (wf("o/r/.github/workflows/server.yml@v1.2.3"), "full 40-character commit SHA"),
        (wf("o/r/.github/workflows/server.yml@main"), "not a tag or branch"),
        (wf(f"o/r/.github/workflows/server.yml@{'A' * 40}"), "full 40-character commit SHA"),
        (wf(f"o/r/.github/workflows/other.yml@{SHA_A}"), "isn't <owner>/<repo>"),
        (wf(f"./.github/workflows/server.yml@{SHA_A}"), "isn't <owner>/<repo>"),
        (wf(f"o/r/.github/workflows/server.yml@{SHA_A} # latest"), "must start with the release"),
        ("jobs: {}\n", "found 0"),
        (
            wf(
                f"o/r/.github/workflows/server.yml@{SHA_A}",
                "  other:\n    steps:\n      - uses: actions/x@v1\n",
            ),
            "found 2",
        ),
    ],
)
def test_pin_errors(text: str, fragment: str) -> None:
    pin, errors = configrepo.read_pin(text)
    assert pin is None and any(fragment in e for e in errors), errors


@pytest.mark.parametrize(
    ("comment", "version"),
    [
        ("# v1.1.0 (upload fix)", "v1.1.0"),  # a note after a space is fine (a live config repo)
        ("#v1.1.0", "v1.1.0"),
        ("# v1.1.0-3-gabcdef1", "v1.1.0-3-gabcdef1"),  # an untagged commit (pinmove.version_of)
        ("# v0.0.0-12-g" + "b" * 40, "v0.0.0-12-g" + "b" * 40),
        ("", None),  # no comment: informational only
    ],
)
def test_pin_comments_that_validate(comment: str, version: str | None) -> None:
    pin, errors = configrepo.read_pin(wf(f"o/r/.github/workflows/server.yml@{SHA_A} {comment}"))
    assert errors == [] and pin == configrepo.Pin("o/r", SHA_A, version)


@pytest.mark.parametrize(
    ("comment", "why"),
    [
        ("v1.1.0+fix", "; `v1.1.0` must be followed by a space, not `+fix`"),
        ("1.1.0", "; the release needs its `v`"),
        ("latest", ""),
    ],
)
def test_bad_pin_comment_says_what_and_shows_a_valid_line(comment: str, why: str) -> None:
    pin, errors = configrepo.read_pin(wf(f"o/r/.github/workflows/server.yml@{SHA_A} # {comment}"))
    assert pin is None
    assert errors == [
        "the pin's comment must start with the release, e.g. "
        "`uses: <owner>/<repo>/.github/workflows/server.yml@<40-hex sha> # v1.1.0` "
        f"(found `# {comment}`{why}); put any note after it: `# v1.1.0 (upload fix)`"
    ]


def test_validate_reports_the_bad_pin_comment_with_the_file(tmp_path) -> None:
    root = make_config_repo(tmp_path / "c")
    wf_path = root / configrepo.WORKFLOW
    wf_path.write_text(wf_path.read_text().replace("# v0.0.0", "# v0.0.0+fix"))
    with pytest.raises(configrepo.ConfigError) as e:
        configrepo.load(root)
    assert any(
        err.startswith(".github/workflows/server.yml: the pin's comment must start with the release")
        and "(found `# v0.0.0+fix`" in err
        for err in e.value.errors
    ), e.value.errors


def test_template_workflow_pin_round_trips(tmp_path) -> None:
    root = make_config_repo(tmp_path / "c")
    pin, errors = configrepo.read_pin((root / configrepo.WORKFLOW).read_text())
    assert errors == [] and pin == configrepo.Pin(configrepo.PRODUCT_REPOSITORY, TEST_SHA, "v0.0.0")


# --- locks and expiry ----------------------------------------------------------------------------------


def locks() -> tuple[dict, dict]:
    return (
        yaml.safe_load((REPO / "template/server.lock.yml").read_text()),
        yaml.safe_load((REPO / "template/plugins.lock.yml").read_text()),
    )


def test_locks_must_match_server_yml(tmp_path) -> None:
    cfg = configrepo.load(make_config_repo(tmp_path / "c")).server
    server, plugins = locks()
    assert configrepo.check_locks(cfg, server, plugins) == []
    bad_server = server | {"minecraft_version": "26.4", "server": server["server"] | {"project": "paper"}}
    errors = configrepo.check_locks(cfg, bad_server, plugins)
    assert any("pins Minecraft '26.4'" in e for e in errors)
    assert any("minecraft.flavour is 'purpur'" in e for e in errors)
    errors = configrepo.check_locks(cfg, server, {"plugins": []})
    assert any("server.yml plugins are" in e for e in errors)
    tampered = {
        "plugins": [plugins["plugins"][0] | {"sha256": "x", "url": "http://x", "filename": "../a.jar"}]
    }
    errors = configrepo.check_locks(cfg, server, tampered)
    assert sum("plugins[0]" in e for e in errors) == 3
    assert configrepo.check_locks(cfg, [], plugins) and configrepo.check_locks(cfg, server, {})


@pytest.mark.parametrize(
    ("data", "ok"),
    [
        ({"credentials": []}, True),
        (
            {
                "credentials": [
                    {"name": "cloudflare-admin", "expires_on": "2027-01-31", "checked_at": "2026-10-31"}
                ]
            },
            True,
        ),
        (
            {"credentials": [{"name": "tailscale-oauth", "expires_on": None, "checked_at": "2026-10-31"}]},
            True,
        ),
        ({"credentials": [{"name": "x", "expires_on": "2027-02-30", "checked_at": "2026-10-31"}]}, False),
        ({"credentials": [{"name": "x", "expires_on": None, "checked_at": None}]}, False),
        ({"credentials": [{"name": "X Y", "expires_on": None, "checked_at": "2026-10-31"}]}, False),
        (
            {"credentials": [{"name": "x", "expires_on": None, "checked_at": "2026-10-31", "value": "s"}]},
            False,
        ),
        ({"credentials": [{"name": "x", "expires_on": None, "checked_at": "2026-10-31"}] * 2}, False),
        ({"tokens": []}, False),
        ([], False),
    ],
)
def test_expiry(data, ok: bool) -> None:
    _, errors = configrepo.check_expiry(data)
    assert (errors == []) is ok, errors


def test_expiry_yaml_dates(tmp_path) -> None:
    root = make_config_repo(tmp_path / "c")
    (root / "expiry.yml").write_text(
        "credentials:\n  - {name: gh-admin, expires_on: 2027-01-31, checked_at: 2026-10-31}\n"
    )
    assert configrepo.load(root).expiry[0]["name"] == "gh-admin"


# --- materialize ---------------------------------------------------------------------------------------


def test_materialize_guards(tmp_path) -> None:
    with pytest.raises(ValueError, match="commit SHA"):
        configrepo.materialize(tmp_path / "a", sha="main", version="v1.0.0")
    with pytest.raises(ValueError, match="version"):
        configrepo.materialize(tmp_path / "a", sha=SHA_A, version="1.0")
    (tmp_path / "b").mkdir()
    (tmp_path / "b" / "keep.txt").write_text("x")
    with pytest.raises(FileExistsError):
        configrepo.materialize(tmp_path / "b", sha=SHA_A, version="v1.0.0")
    configrepo.materialize(tmp_path / "b", sha=SHA_A, version="v1.0.0", overwrite=True)
    assert (tmp_path / "b" / "keep.txt").read_text() == "x"
    text = (tmp_path / "b" / configrepo.WORKFLOW).read_text()
    assert f"uses: {configrepo.PRODUCT_REPOSITORY}/.github/workflows/server.yml@{SHA_A} # v1.0.0" in text
    assert "__PRODUCT_" not in "".join(p.read_text() for p in (tmp_path / "b").rglob("*") if p.is_file())


def test_ci_expects_the_config_repo_to_name_itself(config_repo, capsys) -> None:
    # The reusable workflow passes --expect-repository "$GITHUB_REPOSITORY" for a real config repo.
    assert (
        cli.main(["validate", "-C", str(config_repo), "--expect-repository", "MCCTL-tests/Tests-MC-Config"])
        == 0
    )
    assert cli.main(["validate", "-C", str(config_repo), "--expect-repository", "someone/else"]) == 1
    assert "but this workflow runs in 'someone/else'" in capsys.readouterr().err
